(5923377, 864006, 106910, '<td valign="top">I like the layout of this photo, but the edges lack clarity.</td>', 'I like the layout of this photo, but the edges lack clarity.', '2010-03-31 10:34:48.000000', NULL, 1),
(5923379, 863835, 106910, '<td valign="top">I love the clarity and color to this shot</td>', 'I love the clarity and color to this shot', '2010-03-31 10:35:28.000000', NULL, 1),
(5923380, 864051, 106910, '<td valign="top">Very nice night shot - entrance for what though?</td>', 'Very nice night shot - entrance for what though?', '2010-03-31 10:35:51.000000', NULL, 1),
(5923382, 864074, 106910, '<td valign="top">The picture feels off balance, with the left door taking up over half the shot. Not a bad thing - the shot''s still very precise - I just feel like the green door should have had more devotion to it.</td>', 'The picture feels off balance, with the left door taking up over half the shot. Not a bad thing - the shot''s still very precise - I just feel like the green door should have had more devotion to it.', '2010-03-31 10:37:07.000000', NULL, 1),
