(5923384, 863786, 106910, '<td valign="top">Very monolithic - I like the grey tones. I think more contrast would have done this photo justice.</td>', 'Very monolithic - I like the grey tones. I think more contrast would have done this photo justice.', '2010-03-31 10:38:08.000000', NULL, 1),
(5923386, 863869, 106910, '<td valign="top">Call me wrong... but this seems like it is abstract for abstract''s sake rather than for some abstract meaning.</td>', 'Call me wrong... but this seems like it is abstract for abstract''s sake rather than for some abstract meaning.', '2010-03-31 10:44:30.000000', NULL, 1),
(5923387, 863089, 106910, '<td valign="top">While I like the lines in this photo - there''s just nothing to hold my attention for longer than a second to say "nice lines". 6</td>', 'While I like the lines in this photo - there''s just nothing to hold my attention for longer than a second to say "nice lines". 6', '2010-03-31 10:45:40.000000', NULL, 1),
(5923389, 863964, 106910, '<td valign="top">I''ll admit - white background just bug me. Still, the clarity of the shot is outstanding, but not sure how I like the idea of any opening being an "entrance".  I guess bugs could go in. 6</td>', 'I''ll admit - white background just bug me. Still, the clarity of the shot is outstanding, but not sure how I like the idea of any opening being an "entrance".  I guess bugs could go in. 6', '2010-03-31 10:47:21.000000', NULL, 1),
