(5923408, 863758, 106910, '<td valign="top">Cute... but plain</td>', 'Cute... but plain', '2010-03-31 11:01:23.000000', NULL, 1),
(5923410, 864008, 106910, '<td valign="top">Had the sky not been so blown out - the photo would have been one of the better ones in here. I like that it''s not a door - but the whole upper third of the picture is white. I know ya can''t control the conditions, but sometimes the time doesn''t warrant the right shot.</td>', 'Had the sky not been so blown out - the photo would have been one of the better ones in here. I like that it''s not a door - but the whole upper third of the picture is white. I know ya can''t control the conditions, but sometimes the time doesn''t warrant the right shot.', '2010-03-31 11:03:01.000000', NULL, 1),
(5923412, 863432, 106910, '<td valign="top">Interesting shot, but it just feels artificial. By this I mean, it looks like a vacation snap-shot. It might be the background that''s distracting me - but the colors are very bland.</td>', 'Interesting shot, but it just feels artificial. By this I mean, it looks like a vacation snap-shot. It might be the background that''s distracting me - but the colors are very bland.', '2010-03-31 11:05:06.000000', NULL, 1),
