(5923414, 863826, 106910, '<td valign="top">Very nice processing, nice light, but the perspective is boring. There are available leading lines going up the stairs... The shot just leaves much to be desired.</td>', 'Very nice processing, nice light, but the perspective is boring. There are available leading lines going up the stairs... The shot just leaves much to be desired.', '2010-03-31 11:06:54.000000', NULL, 1),
(5923418, 863849, 114472, '<td valign="top">Photoshop?!</td>', 'Photoshop?!', '2010-03-31 11:11:19.000000', NULL, 1),
(5923419, 863128, 106910, '<td valign="top">I like this shot - and I guess for the challenge he''s entering into the water. Honestly then, I would have shot this photo from leg level to show him actually entering the water. Wide-angle should still let you have mostly the same perspective.</td>', 'I like this shot - and I guess for the challenge he''s entering into the water. Honestly then, I would have shot this photo from leg level to show him actually entering the water. Wide-angle should still let you have mostly the same perspective.', '2010-03-31 11:11:35.000000', NULL, 1),
(5923420, 863183, 106910, '<td valign="top">I don''t know how to capture the "Grizzly Gateway" better, but I''m not really drawn into the picture.</td>', 'I don''t know how to capture the "Grizzly Gateway" better, but I''m not really drawn into the picture.', '2010-03-31 11:12:23.000000', NULL, 1),
(5923424, 863253, 106910, '<td valign="top">Trying not to... The cereal looks pixelated in the light.</td>', 'Trying not to... The cereal looks pixelated in the light.', '2010-03-31 11:14:03.000000', NULL, 1),
(5923426, 863567, 106910, '<td valign="top">I just don''t feel "spring" in the photo</td>', 'I just don''t feel "spring" in the photo', '2010-03-31 11:16:59.000000', NULL, 1),
(5923430, 863926, 106910, '<td valign="top">Clever - but it''s still just a picture of two pills. If this same shot was done in someone''s hand, with dark background, it would have been much, much better. The white background just makes it look staged and... well... stale.</td>', 'Clever - but it''s still just a picture of two pills. If this same shot was done in someone''s hand, with dark background, it would have been much, much better. The white background just makes it look staged and... well... stale.', '2010-03-31 11:19:00.000000', NULL, 1),
(5923434, 863979, 106910, '<td valign="top">Different perspective would have helped here - the house takes too much away from the path (or entrance in this case). Perhaps a low-level shot from the right or left, getting both bushes into the frame and the focus on the path?</td>', 'Different perspective would have helped here - the house takes too much away from the path (or entrance in this case). Perhaps a low-level shot from the right or left, getting both bushes into the frame and the focus on the path?', '2010-03-31 11:21:03.000000', NULL, 1),
(5923436, 863931, 106910, '<td valign="top">Very precise shot, I just wish there was more to the shot than the arch being a frame for... trees.</td>', 'Very precise shot, I just wish there was more to the shot than the arch being a frame for... trees.', '2010-03-31 11:22:07.000000', NULL, 1),
