INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5937502, 863855, 103142, '<td valign="top">Loved this one -- gave it a 9<br/> <br/>also, I think it should have a bluebird!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=811107" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg"/></a> <br/><a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=971036&amp;page=1#5937500" rel="nofollow" target="_blank">Posthumous ribbons thread</a></td>', 'Loved this one -- gave it a 9 also, I think it should have a bluebird! Posthumous ribbons thread', '2010-04-08 15:04:14.000000', NULL, 0),
(5937505, 863809, 103142, '<td valign="top">I loved the idea of the posthumous ribbons thread, so I created my own, silly ribbon. Anyway, I thought this was a great photo -- I gave it an 8! So, here, have a bluebird!<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=811107" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg"/></a> <br/><a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=971036&amp;page=1#5937500" rel="nofollow" target="_blank">posthumous ribbon thread</a></td>', 'I loved the idea of the posthumous ribbons thread, so I created my own, silly ribbon. Anyway, I thought this was a great photo -- I gave it an 8! So, here, have a bluebird!  posthumous ribbon thread', '2010-04-08 15:06:06.000000', NULL, 0),
